#include <bits/stdc++.h>
using namespace std;
bool isPrime(long long x){
    if (x < 2) return false;
    for (long long i = 2; i*i <= x; i++) if (x % i == 0) return false;
    return true;
}
int main(){
    vector<bool> primeFlag(10001);
    for (int n = 0; n <= 10000; n++) primeFlag[n] = isPrime((long long)n*n + n + 41);
    int a, b;
    while (cin >> a >> b) {
        int cnt = 0;
        for (int n = a; n <= b; n++) if (primeFlag[n]) cnt++;
        double pct = 100.0 * cnt / (b - a + 1);
        printf("%.2f\n", pct);
    }
}

